pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address userA = address(0xdead);
        address userB = address(0xbeef);

        // Fund users
        vm.deal(userA, 2 wei);
        vm.deal(userB, 1 wei);

        // User A deposits 2 wei
        vm.prank(userA);
        c.deposit{value: 2 wei}();

        // User B deposits 1 wei
        vm.prank(userB);
        c.deposit{value: 1 wei}();

        // User A withdrawAll
        vm.prank(userA);
        c.withdrawAll();

        // After A's withdrawal, reference: 2 - 2 + 1 = 1 wei in contract
        // Mutant: 2 + 1 = 3 wei (since balance not updated) but A got 2 wei, so contract = 1 wei
        // Actually mutant: balance never updated, so address(c).balance = 3 - 2 = 1 wei
        // Wait, need to check: after deposits, contract balance = 3 wei. After A withdraws 2 wei, contract balance = 1 wei in both because EVM transfer reduces actual ether.
        // The difference is in the public balance variable.
        // assertEq(c.balance(), 1); for reference, c.balance() returns 1; for mutant, c.balance() returns 3.
        assertTrue(c.balance() == 1);
    }
}

