pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract MaliciousRecipient {
    receive() external payable {
        revert("I reject ETH");
    }
}

contract InvMutTest is Test {
    C c;
    MaliciousRecipient malicious;
    function setUp() public {
        c = new C();
        malicious = new MaliciousRecipient();
    }
    function testRegression_property() public {
        // Fund the malicious contract so it can pay the deposit
        vm.deal(address(malicious), 1 ether);

        // Malicious contract deposits 1 wei into C
        vm.prank(address(malicious));
        c.deposit{value: 1 wei}();

        // Now malicious contract tries to withdrawAll — the call will revert
        // For the correct contract, the require causes the whole tx to revert
        // For the buggy, the call fails silently, balance/credit already changed

        uint256 balanceBefore = address(c).balance;
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // The assertion: the reference contract reverts (success == false),
        // the buggy one returns true (success == true) — diverging behavior
        assertTrue(!success);
    }
}

