import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Malicious recipient that always reverts on receive
    contract Malicious {
        receive() external payable { revert("I refuse ether"); }
    }

    function testRegression_property() public {
        Malicious mal = new Malicious();
        address user = address(mal);

        // Fund the contract with 1 wei via deposit from the malicious contract
        vm.deal(user, 1 wei);
        vm.prank(user);
        c.deposit{value: 1 wei}();

        // Now user tries to withdrawAll: correct version reverts, buggy version does not
        uint balBefore = address(c).balance;
        (bool success, ) = address(c).call(abi.encodeCall(c.withdrawAll, ()));
        if (address(c).balance == balBefore) {
            // revert happened: correct behavior
            assertTrue(true);
        } else {
            // no revert: buggy behavior
            assertTrue(false);
        }
    }
}

