pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a malicious receiver that reverts on receive
        address receiver = address(new Malicious());
        vm.deal(receiver, 0);
        // Fund receiver with 1 wei so it can withdraw
        vm.deal(address(this), 1 wei);
        vm.prank(receiver);
        c.deposit{value: 1 wei}();
        // Try withdrawAll from receiver — correct version reverts, buggy version does not
        bool ok;
        try Malicious(receiver).triggerWithdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }
        // In the correct version, the call reverts so ok is false
        // In the buggy version, the call succeeds so ok is true
        assertTrue(!ok);
    }
}

contract Malicious {
    C c;
    constructor() {}
    function setC(address _c) external { c = C(_c); }
    function triggerWithdrawAll() external {
        c.withdrawAll();
    }
    fallback() external payable {
        revert("no");
    }
    receive() external payable {
        revert("no");
    }
}

