pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a malicious contract that reenters withdrawAll
        MaliciousReenter reenter = new MaliciousReenter(c);

        // Fund the malicious contract with 1 wei
        vm.deal(address(reenter), 1);

        // Deposit 1 wei through the malicious contract
        vm.prank(address(reenter));
        c.deposit{value: 1}();

        // Now trigger withdrawal, which will cause a reentrant call
        vm.prank(address(reenter));
        c.withdrawAll();

        // After the reentrant attack, check the reference holds balance = 0
        // In the buggy version, balance will be -1 (underflow), causing revert when calling withdrawAll again
        // We assert that the second withdrawAll succeeds (no revert) on the reference
        // For the buggy version, this will revert
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract MaliciousReenter {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable {
        if (address(this).balance > 0) {
            c.withdrawAll();
        }
    }
}

